int main(int argc,char** argv){try{if(argc<2){std::cerr<<"usage: cieav-windows-tpm-native-attestation <probe|describe-aik|inspect-aik|collect|verify> ...\n";return 2;}std::string cmd=argv[1];if(cmd=="probe")return probe();if(cmd=="describe-aik")return describeAik(argc,argv);if(cmd=="inspect-aik")return inspectAik(argc,argv);if(cmd=="collect")return collect(argc,argv);if(cmd=="verify")return verify(argc,argv);std::cerr<<"unsupported command\n";return 2;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 20;}}
